<?php
/** Proof — matching (spec "Proof", 2): the deposit line's one candidate; a payment; a fee as an entry; the to-the-cent rule; a receipt to undeposited funds not offered; unmatch; ignore. */
require __DIR__ . '/lib.php';
$bea = as_member(27); $carl = as_member(28); $vera = as_member(26);
$w = cash_world(); $L = may_lines($w);
echo "1. The match page and the candidates\n";
$body = page($bea, '/cash/match?bank_account=' . $w['chk'])['body'];
ok(str_contains($body, 'id="bank-line-' . $L['REF-1'] . '"') && str_contains($body, 'id="bank-figures"') && str_contains($body, 'id="bank-match-auto-btn"') && str_contains($body, 'sure one'), 'the page: a card per unmatched line, the figures, the "match the sure ones" button');
$c1 = line_candidates_json($bea, $L['REF-1'], $w);
function line_candidates_json(string $jar, int $line, array $w): array { $d = screen($jar, '/cash/match?bank_account=' . $w['chk'])[1]; foreach ($d['lines'] ?? [] as $l) { if ($l['bank_transaction_id'] === $line) { return $l['candidates']; } } return []; }
ok(count($c1) === 1 && $c1[0]['item_type'] === 'receipt' && $c1[0]['item_id'] === $w['r1'] && $c1[0]['amount'] === '1608.24' && $c1[0]['days_apart'] === 1, 'the Acme line has one candidate: the receipt banked straight to Checking (1 day apart)');
$c2 = line_candidates_json($bea, $L['REF-2'], $w);
ok(count($c2) === 1 && $c2[0]['item_type'] === 'deposit' && $c2[0]['item_id'] === $w['d1'] && $c2[0]['amount'] === '800.00', 'the deposit line\'s one candidate is the deposit — the undeposited receipt of 800.00 (R4) is NOT offered');
$c3 = line_candidates_json($bea, $L['REF-3'], $w);
ok(count($c3) === 1 && $c3[0]['item_type'] === 'payment' && $c3[0]['item_id'] === $w['p1'] && $c3[0]['amount'] === '-259.80', 'the hosting line\'s candidate is the payment (signed −259.80)');
ok(line_candidates_json($bea, $L['REF-4'], $w) === [], 'the fee has no candidate; the card says what to do');
$body = page($bea, '/cash/match?bank_account=' . $w['chk'])['body'];
ok(str_contains($body, 'id="bank-line-' . $L['REF-4'] . '-nocandidate"') && str_contains($body, 'Record the payment first') && str_contains($body, 'id="bank-line-' . $L['REF-4'] . '-entry"') && str_contains($body, 'id="bank-line-' . $L['REF-4'] . '-ignore"'), 'a line with no candidate says "record the payment first — or make an entry"; Make an entry and Ignore are there');
[$c, $b] = act($bea, '/cash/match.php', ['bank_line' => $L['REF-2'], 'item_type' => 'receipt', 'item' => $w['r4']]);
ok($c === 422 && str_contains(msg($b), 'No recorded receipt ' . $w['r4'] . ' on this bank account'), 'the undeposited receipt cannot be matched either: 422 "No recorded receipt … on this bank account"');
echo "2. Match\n";
pdo()->exec("SELECT set_config('app.member_id', '1', false)");
$cleared0 = (string) one('SELECT cleared_balance FROM mcp_bank_accounts WHERE bank_account_id = :b', ['b' => $w['chk']]);
ok($cleared0 === '10000.00', 'the cleared balance starts at the opening balance (10,000.00)');
$since = last_activity_id();
$r = req('POST', '/cash/match.php', ['jar' => $bea, 'headers' => ['HX-Request: true', 'HX-Target: bank-line-' . $L['REF-2']], 'form' => ['bank_line' => $L['REF-2'], 'item_type' => 'deposit', 'item' => $w['d1'], 'csrf_token' => csrf_of(page($bea, '/')['body'])]]);
ok($r['code'] === 200 && !str_contains($r['body'], 'bank-line-' . $L['REF-2'] . '"') && str_contains($r['body'], 'id="bank-figures" hx-swap-oob="true"') && str_contains($r['body'], 'bankChanged') === false, 'under HTMX the card is swapped out and the figures come back out of band');
ok(str_contains($r['headers'], 'HX-Trigger') && str_contains($r['headers'], 'bankChanged'), 'with HX-Trigger bankChanged');
$row = q('SELECT * FROM bank_transactions WHERE id = :i', ['i' => $L['REF-2']])[0];
ok($row['status'] === 'matched' && $row['matched_type'] === 'deposit' && (int) $row['matched_id'] === $w['d1'] && (int) $row['matched_by'] === 27 && $row['matched_at'] !== null, 'the deposit line is matched to the deposit by 27');
pdo()->exec("SELECT set_config('app.member_id', '1', false)");
ok((string) one('SELECT cleared_balance FROM mcp_bank_accounts WHERE bank_account_id = :b', ['b' => $w['chk']]) === '10800.00', 'the cleared balance is up by the line: 10,800.00');
$l = activity('bank.match', $since)[0]; $a = json_decode((string) $l['after'], true);
ok((int) $l['bank_account_id'] === $w['chk'] && $a['bank_transaction_id'] === $L['REF-2'] && $a['item_type'] === 'deposit' && $a['item_id'] === $w['d1'] && $a['amount'] === '800.00', 'bank.match logs bank_account_id, bank_transaction_id, item_type, item_id and amount');
[$c, $b] = act($bea, '/cash/match.php', ['bank_line' => $L['REF-1'], 'item_type' => 'receipt', 'item' => $w['r1']]);
ok($c === 200 && ($b['amount'] ?? '') === '1608.24' && ($b['location'] ?? '') === '/cash/match?bank_account=' . $w['chk'] . '&notice=matched', 'bank_transaction_match (JSON): 200 with the amount and the match page as location');
[$c, $b] = act($bea, '/cash/match.php', ['bank_line' => $L['REF-3'], 'item_type' => 'payment', 'item' => $w['p1']]);
ok($c === 200 && line_status($L['REF-3']) === 'matched', 'the payment line matched to its payment');
pdo()->exec("SELECT set_config('app.member_id', '1', false)");
ok((string) one('SELECT cleared_balance FROM mcp_bank_accounts WHERE bank_account_id = :b', ['b' => $w['chk']]) === '12148.44', 'cleared after the three matches: 10,000 + 800 + 1,608.24 − 259.80 = 12,148.44');
echo "3. The to-the-cent rule\n";
$odd = bank_line_row($w['chk'], '2026-05-10', '1000.00', 'SMOKE odd amount', 'ODD-1');
[$c, $b] = act($bea, '/cash/match.php', ['bank_line' => $odd, 'item_type' => 'deposit', 'item' => $w['d1']]);
ok($c === 422 && str_contains(msg($b), 'The deposit is 800.00 but the bank line is 1000.00: a match is to the cent'), '422 "The deposit is 800.00 but the bank line is 1000.00: a match is to the cent"');
[$c, $b] = act($bea, '/cash/match.php', ['bank_line' => $odd, 'item_type' => 'deposit', 'item' => 424242]);
ok($c === 422 && str_contains(msg($b), 'No recorded deposit 424242 on this bank account'), '422 "No recorded deposit 424242 on this bank account"');
[$c, $b] = act($bea, '/cash/match.php', ['bank_line' => $L['REF-2'], 'item_type' => 'deposit', 'item' => $w['d1']]);
ok($c === 422 && str_contains(msg($b), 'Bank line ' . $L['REF-2'] . ' is matched'), 'a matched line is not matched again: 422 "Bank line N is matched"');
[$c, $b] = act($bea, '/cash/match.php', ['bank_line' => $odd, 'item_type' => 'bogus', 'item' => 1]);
ok($c === 422 && str_contains(msg($b), 'item_type is receipt'), 'an unknown item type: 422');
[$c, $b] = act($bea, '/cash/match.php', ['bank_line' => 424242, 'item_type' => 'deposit', 'item' => 1]);
ok($c === 404, 'an unknown bank line: 404');
[$c, $b] = act($vera, '/cash/match.php', ['bank_line' => $odd, 'item_type' => 'deposit', 'item' => $w['d1']]);
ok($c === 403, 'a Viewer matching: 403');
ok(req('GET', '/cash/match', ['jar' => $vera])['code'] === 403, 'a Viewer opening the match page: 403');
echo "4. A fee and interest become entries\n";
$since = last_activity_id();
[$c, $b] = act($bea, '/cash/entry.php', ['bank_line' => $L['REF-4'], 'account' => account_id('1200')]);
ok($c === 422 && str_contains(msg($b), 'control account'), 'an entry against a control account (1200): 422 "… is a control account; record a receipt or a payment instead"');
[$c, $b] = act($bea, '/cash/entry.php', ['bank_line' => $L['REF-4'], 'account' => account_id('6500'), 'memo' => 'SMOKE May bank fee']);
$fee = q('SELECT * FROM bank_transactions WHERE id = :i', ['i' => $L['REF-4']])[0];
ok($c === 200 && $fee['status'] === 'matched' && $fee['matched_type'] === 'journal_entry' && ($b['journal_entry_number'] ?? '') !== '' && (int) $fee['matched_id'] === (int) $b['journal_entry_id'], 'bank_entry_from_line: the fee is matched to the entry it posted');
$e = q('SELECT * FROM journal_entries WHERE id = :e', ['e' => $fee['matched_id']])[0];
$jl = array_column(q('SELECT a.code, l.debit, l.credit FROM journal_lines l JOIN accounts a ON a.id = l.account_id WHERE l.entry_id = :e', ['e' => $e['id']]), null, 'code');
ok($e['status'] === 'posted' && $e['source'] === 'bank_fee' && $e['entry_date'] === '2026-05-31' && $e['memo'] === 'SMOKE May bank fee' && $jl['6500']['debit'] === '15.00' && $jl['1010']['credit'] === '15.00', 'the entry: posted 2026-05-31, source bank_fee, DR 6500 15.00 / CR 1010 15.00');
$l = activity('bank.entry_from_line', $since)[0]; $a = json_decode((string) $l['after'], true);
ok((int) $l['journal_entry_id'] === (int) $e['id'] && (int) $l['bank_account_id'] === $w['chk'] && $a['account_code'] === '6500' && $a['amount'] === '-15.00' && str_starts_with($a['journal_entry_number'], 'JE-'), 'bank.entry_from_line logs journal_entry_id, bank_account_id, account_code, amount and the entry number');
[$c, $b] = act($bea, '/cash/entry.php', ['bank_line' => $L['REF-5'], 'account' => account_id('7000')]);
$int = q('SELECT * FROM bank_transactions WHERE id = :i', ['i' => $L['REF-5']])[0];
$ie = q('SELECT source, memo FROM journal_entries WHERE id = :e', ['e' => $int['matched_id']])[0];
$ijl = array_column(q('SELECT a.code, l.debit, l.credit FROM journal_lines l JOIN accounts a ON a.id = l.account_id WHERE l.entry_id = :e', ['e' => $int['matched_id']]), null, 'code');
ok($c === 200 && $ie['source'] === 'bank_interest' && $ie['memo'] === 'INTEREST' && $ijl['1010']['debit'] === '4.10' && $ijl['7000']['credit'] === '4.10', 'interest: DR 1010 4.10 / CR 7000, source bank_interest, the memo defaults to the line\'s description');
[$c, $b] = act($bea, '/cash/entry.php', ['bank_line' => $L['REF-5'], 'account' => account_id('7000')]);
ok($c === 422 && str_contains(msg($b), 'is matched'), 'an entry from a matched line: 422');
[$c, $b] = act($vera, '/cash/entry.php', ['bank_line' => $odd, 'account' => account_id('6500')]);
ok($c === 403, 'a Viewer making an entry: 403');
echo "5. Unmatch and ignore\n";
$since = last_activity_id();
[$c, $b] = act($bea, '/cash/unmatch.php', ['bank_line' => $L['REF-3']]);
$u = q('SELECT * FROM bank_transactions WHERE id = :i', ['i' => $L['REF-3']])[0];
ok($c === 200 && $u['status'] === 'unmatched' && $u['matched_type'] === null && $u['matched_by'] === null, 'bank_transaction_unmatch frees the line');
$l = activity('bank.unmatch', $since)[0]; $bf = json_decode((string) $l['before'], true);
ok($bf['item_type'] === 'payment' && (int) $bf['item_id'] === $w['p1'] && (int) $l['bank_account_id'] === $w['chk'], 'bank.unmatch logs what it was matched to');
[$c, $b] = act($bea, '/cash/unmatch.php', ['bank_line' => $L['REF-3']]);
ok($c === 422 && str_contains(msg($b), 'is not matched'), 'unmatching a free line: 422');
act($bea, '/cash/match.php', ['bank_line' => $L['REF-3'], 'item_type' => 'payment', 'item' => $w['p1']]);
$since = last_activity_id();
[$c, $b] = act($bea, '/cash/ignore.php', ['bank_line' => $odd, 'reason' => '']);
ok($c === 422 && str_contains(msg($b), 'Ignoring a bank line needs a reason'), 'ignore without a reason: 422');
[$c, $b] = act($bea, '/cash/ignore.php', ['bank_line' => $L['REF-3'], 'reason' => 'x']);
ok($c === 422 && str_contains(msg($b), 'is matched'), 'a matched line cannot be ignored');
$r = req('POST', '/cash/ignore.php', ['jar' => $bea, 'headers' => ['HX-Request: true', 'HX-Target: bank-line-' . $odd], 'form' => ['bank_line' => $odd, 'reason' => 'SMOKE a duplicate of a line already here', 'csrf_token' => csrf_of(page($bea, '/')['body'])]]);
$ig = q('SELECT * FROM bank_transactions WHERE id = :i', ['i' => $odd])[0];
ok($r['code'] === 200 && $ig['status'] === 'ignored' && $ig['ignore_reason'] === 'SMOKE a duplicate of a line already here' && str_contains($r['body'], 'id="bank-figures" hx-swap-oob="true"'), 'bank_transaction_ignore: ignored with its reason (under HTMX the card goes, the figures return)');
$l = activity('bank.ignore', $since)[0]; $a = json_decode((string) $l['after'], true);
ok($a['reason'] === 'SMOKE a duplicate of a line already here' && $a['amount'] === '1000.00' && (int) $l['bank_account_id'] === $w['chk'], 'bank.ignore logs the reason and amount');
pdo()->exec("SELECT set_config('app.member_id', '1', false)");
ok((string) one('SELECT cleared_balance FROM mcp_bank_accounts WHERE bank_account_id = :b', ['b' => $w['chk']]) === (string) one('SELECT 10000 + 1608.24 + 800 - 259.80 - 15 + 4.10'), 'an ignored line counts for nothing: cleared = 10,000 + 1,608.24 + 800 − 259.80 − 15 + 4.10 = 12,137.54');
[$c, $b] = act($bea, '/cash/unmatch.php', ['bank_line' => $odd]);
ok($c === 200 && line_status($odd) === 'unmatched', 'unmatch frees an ignored line too');
act($bea, '/cash/ignore.php', ['bank_line' => $odd, 'reason' => 'SMOKE again']);
echo "6. The pages\n";
$d = screen($bea, '/cash/match?bank_account=' . $w['chk'])[1];
ok(($d['bank_account']['bank_account_id'] ?? 0) === $w['chk'] && array_intersect(array_values($L), array_column($d['lines'] ?? [], 'bank_transaction_id')) === [] && ($d['may']['entry'] ?? false) === true, 'JSON: the match screen answers; none of the five May lines is left among the unmatched');
$body = page($bea, '/cash/match?bank_account=' . $w['chk'])['body'];
ok(!str_contains($body, 'id="bank-line-' . $L['REF-1'] . '"') && !str_contains($body, 'id="bank-line-' . $L['REF-4'] . '"') && !str_contains($body, 'id="bank-line-' . $odd . '"'), 'the matched, entered and ignored lines are no longer cards');
bank_line_row($w['chk'], '2026-06-01', '-2000.00', 'SMOKE CHEQUE 2001', 'REF-C1');
$body = page($bea, '/cash/match?bank_account=' . $w['chk'] . '&auto=1')['body'];
ok(str_contains($body, 'id="bank-match-auto-btn"') && str_contains($body, 'data-sure="1"') && str_contains($body, 'run();'), 'a line with one candidate (the cheque) is "sure"; ?auto=1 has the page click it');
$d = screen($vera, '/cash/banks/' . $w['chk'])[1];
ok(($d['may']['write'] ?? true) === false && count($d['lines'] ?? []) >= 5, 'a Viewer sees the bank account and its lines (documents.view), without the actions');
finish();
